     1	// Load dotenv FIRST
     2	import * as dotenv from 'dotenv';
     3	dotenv.config({ override: true }); // override inherited env vars
     4	import cron from 'node-cron';
     5	import { createNormalizerWorker } from './queue';
     6	import { processRawEvent } from './normalizer';
     7	import { scrapeTicketmaster } from './sources/ticketmaster';
     8	import { scrapeEventbrite } from './sources/eventbrite';
     9	import { scrapeBilletto } from './sources/billetto';
    10	import { scrapeStockholm, generateStockholmSamples } from './sources/stockholm';
    11	import { initSearchIndex, isMeilisearchConfigured } from './search';
    12	import { startSearchWorker } from './searchWorker';
    13	import { getQueueStats, fetchNextExpansionCandidates, processExpansionBatch } from './discovery/expansionWorker';
    14	import { runMultiHopDiscovery } from './discovery/multiHopDiscovery';
    15	import { seedStockholmVenues, getSeedStatus } from './discovery/stockholmSeeding';
