    17	async function runSources() {
    18	  console.log('[ingestion] Running source scrapers...');
    19	  
    20	  // Stockholm is ALWAYS first - highest priority city
    21	  const sources = [
    22	    { name: 'stockholm', fn: scrapeStockholm, priority: 1 },
    23	    { name: 'ticketmaster', fn: scrapeTicketmaster, priority: 2 },
    24	    { name: 'eventbrite', fn: scrapeEventbrite, priority: 3 },
    25	    { name: 'billetto', fn: scrapeBilletto, priority: 4 },
    26	  ];
    27	  
    28	  // Sort by priority (Stockholm first)
    29	  sources.sort((a, b) => a.priority - b.priority);
    30	  console.log(`[ingestion] Source order: ${sources.map(s => s.name).join(', ')}`);
    31	
    32	  const results = await Promise.allSettled(
    33	    sources.map((s) => s.fn())
    34	  );
    35	
    36	  // Detailed status reporting per source
    37	  let successCount = 0;
    38	  let failCount = 0;
    39	  let skipCount = 0;
    40	  
    41	  sources.forEach((s, i) => {
    42	    if (results[i].status === 'fulfilled') {
    43	      const status = results[i].value;
    44	      if (status === 'skipped') {
    45	        skipCount++;
    46	        console.log(`[ingestion] ⏭️ ${s.name} skipped`);
    47	      } else {
    48	        successCount++;
    49	        console.log(`[ingestion] ✅ ${s.name} completed`);
    50	      }
    51	    } else {
    52	      failCount++;
    53	      const reason = (results[i] as PromiseRejectedResult).reason;
    54	      console.error(`[ingestion] ❌ ${s.name} failed: ${reason?.message || reason}`);
    55	    }
    56	  });
    57	
    58	  console.log(`[ingestion] Summary: ${successCount} succeeded, ${skipCount} skipped, ${failCount} failed`);
    59	
    60	  // Fetch next batch of expansion candidates from the queue
    61	  const candidates = await fetchNextExpansionCandidates(5);
    62	  if (candidates.length > 0) {
    63	    console.log('[ingestion] Next expansion candidates:');
    64	    for (const c of candidates) {
    65	      console.log(`  - ${c.candidate_name} (${c.city}) priority=${c.priority_score}`);
    66	    }
    67	
    68	    // Process expansion batch - this creates results in discovery_expansion_results
    69	    await processExpansionBatch(5);
    70	  }
    71	}
    72	
    73	function startNormalizerWorker() {
    74	  const worker = createNormalizerWorker(processRawEvent);
    75	
    76	  worker.on('completed', (job) => {
    77	    console.log(`[normalizer] Job ${job.id} completed`);
    78	  });
    79	
    80	  worker.on('failed', (job, err) => {
    81	    console.error(`[normalizer] Job ${job?.id} failed:`, err.message);
    82	  });
    83	
    84	  console.log('[normalizer] Worker started');
    85	  return worker;
    86	}
