    93	
    94	  // Seed Stockholm venues for discovery ranking
    95	  console.log('[ingestion] Seeding Stockholm venues...');
    96	  const seededCount = await seedStockholmVenues();
    97	  console.log(`[ingestion] Seeded ${seededCount} Stockholm venues`);
    98	
    99	  // Show seed status
   100	  const status = await getSeedStatus();
   101	  console.log(`[ingestion] Discovery status: ${status.total} total, ${status.stockholm} Stockholm, ${status.seeded} seeded`);
   102	
   103	  // Start the normalizer worker
   104	  startNormalizerWorker();
   105	
   106	  // Start the search sync worker (only if Meilisearch is configured)
   107	  if (isMeilisearchConfigured()) {
   108	    startSearchWorker();
   109	  } else {
   110	    console.warn('[ingestion] Meilisearch not configured, search worker disabled');
   111	  }
   112	
   113	  // Run immediately on startup
   114	  await runSources();
   115	
   116	  // Schedule: every 30 minutes
   117	  cron.schedule('*/30 * * * *', async () => {
   118	    await runSources();
   119	  });
   120	
   121	  console.log('[ingestion] Scheduler running. Scraping every 30 minutes.');
   122	
