   124	  setInterval(async () => {
   125	    const stats = await getQueueStats();
   126	    console.log(`[ingestion] Expansion queue: ${stats.pending} pending, ${stats.processing} processing, ${stats.expanded} expanded`);
   127	  }, 5 * 60 * 1000); // Every 5 minutes
